int *loadData(char *fileName,int N)
{
int *array = (int*)malloc(sizeof(int)*N);
FILE *fp;
int i;
fp = fopen(fileName,"r");
if (fp)
{
for (i=0;i<N;i++)
{
fscanf(fp,"%d",&array[i]);
}
fclose(fp);
return array;
}
else
return NULL;
}
14
int writeArray2File(char *fileName,int *array,int N)
{
FILE *fp;
int i;
fp = fopen(fileName,"w");
if (fp)
{ 
for (i=0;i<N;i++)
{
fprintf(fp,"%d\n",array[i]);
}
fclose(fp);
return 1;
}
else
return -1;
}
